#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<long long> a(n), prefix(n + 1);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        prefix[i + 1] = prefix[i] + a[i];
    }
    while (q--) {
        int l, r;
        cin >> l >> r;
        --l; --r;
        cout << prefix[r + 1] - prefix[l] << '\n';
    }
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<long long> diff(n + 1);
    while (q--) {
        int l, r, x;
        cin >> l >> r >> x;
        --l; --r;
        diff[l] += x;
        diff[r + 1] -= x;
    }
    long long cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        cout << cur << " \n"[i == n - 1];
    }
    return 0;
}
